function solve(a,b){const c=Array.from(b);const d=c.length;for(let i=0;i<d;i++){if(c[i]==='*'&&(i===0||c[i-1]==='*')){return false;}}let e=new Uint8Array(d+1);e[0]=1;for(let i=2;i<=d;i++){if(c[i-1]==='*'){e[i]=e[i-2];}}for(const x of a){const a=new Uint8Array(d+1);for(let i=1;i<=d;i++){const b=c[i-1];if(b==='*'){const b=c[i-2];const d=b==='.'||b===x;a[i]=a[i-2]||d&&e[i]?1:0;}else{a[i]=e[i-1]&&(b==='.'||b===x)?1:0;}}e=a;}return e[d]===1;}
